'use strict';
const interestFields=[
['all','전체 과목',/./,[]],
['humanities','언어·인문',/국어|독서|문학|화법|언어|작문|영어|영미|일본|중국|독일|프랑스|스페인|한문|역사|세계사|동아시아|철학/,['국어국문학과','영어영문학과','사학과']],
['society','사회·경영',/사회|지리|정치|법과 사회|법학|경제|윤리|심리|창업|확률|통계/,['경영학과','경제학과','사회학과']],
['science','수학·기초과학',/수학|대수|미적분|기하|확률|통계|물리|화학|생명|지구|과학/,['수학과','물리학과','생명과학과']],
['engineering','공학·컴퓨터',/수학|대수|미적분|기하|확률|통계|물리|화학|정보|인공지능|기술|공학|프로그래밍/,['기계공학과','전자공학과','컴퓨터공학과']],
['health','보건·의료',/생명|화학|보건|확률|통계|심리|운동/,['간호학과','물리치료학과','의학과']],
['arts','예술·디자인',/미술|음악|예술|디자인|매체|영상|문학/,['시각디자인학과','음악학과','영상학과']],
['sports','체육·스포츠',/체육|스포츠|운동|보건|생명/,['체육학과','스포츠과학과','체육교육과']]
];
(()=>{
let subjectGroup='all',exportPages=[],exportFormat='jpg',exportIndex=0,exportToken=0;
const groups=interestFields;
function docsFor(s,cat){return s.documents.filter(d=>d.category===cat)}
function sourceDetails(s,cat){let docs=docsFor(s,cat);return `<details class="source-details"><summary>${cat} 원본 <span>${docs.length}개 ↗</span></summary><div class="source-links">${docs.map(d=>`${external(d.url,esc(d.title),'source-link')}<small>${esc(d.period)}${d.ocrPages?' · 스캔 문자 인식 포함':!d.textUrl?' · 본문 확인 보류':''}</small>`).join('')}</div></details>`}
function curriculumBrief(s){let c=s.curriculumSummary;if(!c)return '';return `<section class="curriculum-brief"><div class="section-label">교육과정 요약</div><h3 class="detail-title">교육과정 한눈에 보기</h3><p class="brief">${esc(c.basis)} 기준입니다. 2027학년도 신입생 확정 편제와는 다를 수 있어요.</p><div class="curriculum-grid">${c.items.map(x=>`<article><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p></article>`).join('')}</div><details class="source-details"><summary>교육과정 원본 보기</summary><p class="hint">PDF ${c.pdfPages.join('·')}쪽 · 원본 표를 대조해 요약했습니다. 선택 묶음과 실제 개설 여부는 원문·학교 안내를 확인해 주세요.</p>${external(c.sourceUrl,esc(c.sourceTitle),'source-link')}</details></section>`}
function compactSubjects(s){
let rows=s.achievement.filter(x=>x.grade>1),all=[...new Set(rows.map(x=>x.subject.replace(/\s*\([\d.]+\)$/,'')))];
let group=groups.find(g=>g[0]===subjectGroup)||groups[0],list=all.filter(x=>group[2].test(x));
return `<section class="field-explorer"><div class="section-label">관심 분야로 과목 살펴보기</div><h3 class="detail-title">무엇을 배우고 싶나요?</h3><p class="brief">아직 진로를 정하지 않았다면 전체 과목부터 둘러보세요. 관심 분야를 누르면 이 학교에서 수업한 관련 과목을 모아 볼 수 있어요.</p><div class="group-buttons" aria-label="관심 분야">${groups.map(g=>`<button data-subjectgroup="${g[0]}" class="${g[0]===group[0]?'selected':''}" aria-pressed="${g[0]===group[0]}">${g[1]}</button>`).join('')}</div>${group[3].length?`<div class="major-examples"><small>이런 대학 학과도 있어요</small><p>${group[3].map(n=>`<span>${esc(n)}</span>`).join('')}</p><small>진로를 떠올려 보는 예시예요. 아래 과목이 해당 학과의 필수 이수 과목을 뜻하지는 않아요.</small></div>`:''}<h4 class="field-subject-title">${group[0]==='all'?'이 학교에서 확인한 과목':esc(group[1])+' 관련 과목'} <small>${list.length}개</small></h4><p class="brief">2026학년도 1학기 공시에서 2·3학년 수강 내역이 확인된 과목입니다.</p><div class="subject-collection">${list.map(n=>`<span>${esc(n)}</span>`).join('')||'<p class="brief">공시 자료에서 관련 과목을 확인하지 못했어요. 미개설을 뜻하지는 않으므로 학교에 문의해 주세요.</p>'}</div><p class="meaning">2027학년도 입학생의 선택 가능 과목은 아래 교육과정과 학교 안내를 함께 확인하세요. 과목별 신청 인원·시간표에 따라 실제 개설 여부가 달라질 수 있어요.</p><details class="source-details"><summary>관심 분야와 대학 학과 안내</summary><p class="hint">관심 분야는 과목을 찾아보기 위한 앱의 분류예요. 한 과목이 여러 분야에 포함될 수 있으며, 학교의 반 편성이나 입시 추천 기준이 아닙니다. 대학 학과명·모집단위와 권장 과목은 대학별 안내를 확인하세요.</p>${external('https://www.work.go.kr/consltJobCarpa/srch/schdpt/schdptSrch.do','고용24 대학 학과정보에서 더 알아보기')}</details></section>${curriculumBrief(s)}${s.scanFiles?'<div class="notice">교육과정 일부는 원본 확인이 필요합니다. 아래 학교 자료를 확인해 주세요.</div>':''}${sourceDetails(s,'교육과정')}`}

function assessmentCards(s){let rows=s.assessmentSummary||[];return `<div class="section-label">2026년 1학년 2학기</div><h3 class="detail-title">시험과 수행평가 비율</h3><p class="brief">국어·수학·영어 성적에 반영되는 비율이에요.</p><div class="assessment-cards">${rows.map(x=>`<article class="assessment-card"><div class="row"><h4>${esc(x.subject)}</h4><span class="tiny-badge">${x.page?'원문 '+x.page+'쪽':'공시 평가계획'}</span></div><div class="ratio-labels"><span>지필평가 <b>${x.exam}%</b></span><span>수행평가 <b>${x.performance}%</b></span></div><div class="ratio-track" role="img" aria-label="지필평가 ${x.exam}%, 수행평가 ${x.performance}%"><span style="width:${x.exam}%"></span><span style="width:${x.performance}%"></span></div></article>`).join('')||'<div class="notice">반영비율을 요약할 수 있는 근거를 아직 확인하지 못했습니다. 아래 학교 공시 자료를 확인해 주세요.</div>'}</div><div class="meaning"><p>수행평가에는 발표·탐구·과제 등이 포함돼요. 자세한 평가 항목은 원본에서 확인할 수 있어요.</p><p>과거 학기 계획으로, 2027학년도 평가 방식은 달라질 수 있습니다.</p></div><details class="source-details"><summary>과목별 원본 보기</summary>${rows.map(x=>`<div class="evidence-row"><b>${esc(x.subject)}</b><p>지필평가 ${x.exam}% · 수행평가 ${x.performance}%</p><small>${esc(x.sourceTitle)}${x.page?' · PDF '+x.page+'쪽':''}</small>${external(x.sourceUrl,'원본 확인')}</div>`).join('')}</details>${sourceDetails(s,'평가계획')}`}
renderDocuments=function(s){docGeneration++;$('#detailBody').innerHTML=detailTab==='curriculum'?compactSubjects(s):assessmentCards(s)};
const originalDetail=renderDetail;
function subjectCard(x){return `<article class="achievement-card"><div class="row"><h4>${esc(x.subject.replace(/\s*\([\d.]+\)$/,''))}</h4><span>과목 평균 <strong>${x.mean.toFixed(1)}</strong>점</span></div><div class="distbar" role="img" aria-label="${esc(x.subject)} A~E 분포">${'ABCDE'.split('').map(k=>`<span style="width:${x[k]??0}%"></span>`).join('')}</div><div class="achievement-values">${'ABCDE'.split('').map(k=>`<span><b>${k}</b> ${x[k]==null?'—':x[k].toFixed(1)+'%'}</span>`).join('')}</div></article>`}
renderAchievement=function(s){let rows=s.achievement.filter(x=>x.grade===grade&&x.subject.includes(subjectSearch));$('#achievementTable').innerHTML=`<p class="brief">${rows.length}개 과목 · 2026학년도 1학기</p><div class="achievement-cards">${rows.map(subjectCard).join('')||'<p class="empty">조건에 맞는 과목이 없습니다.</p>'}</div>`};
renderDetail=function(){let s=school(detailSchool);if(detailTab==='achievement'){let core=s.achievement.filter(x=>x.grade===1&&/공통(국어|수학|영어)1/.test(x.subject));$('#detailBody').innerHTML=`<div class="section-label">2026년 1학년 1학기</div><h3 class="detail-title">국어·수학·영어 성취도</h3><p class="brief">A~E는 성취 수준별 학생 비율이에요.</p><div class="achievement-cards">${core.map(subjectCard).join('')}</div><div class="meaning">시험 난도와 수강 학생이 달라 학교 평균만으로 내신 유불리나 학교 수준을 판단하기는 어려워요.</div><details class="source-details"><summary>다른 학년·과목 보기</summary><div class="gradecontrol"><label for="grade">학년</label><select id="grade">${[1,2,3].map(n=>`<option value="${n}" ${grade===n?'selected':''}>${n}학년</option>`).join('')}</select><input id="subjectSearch" type="search" placeholder="과목명 검색" aria-label="성취도 과목 검색" value="${esc(subjectSearch)}"></div><div id="achievementTable"></div></details><p class="sourcefoot">2026년 9월 공시 · 평균: 점, 분포: % · 공란은 미제공입니다. ${external(s.source,'학교알리미')}</p>`;renderAchievement(s);return}
if(detailTab==='graduates'){let g=graduate(s);$('#detailBody').innerHTML=`<div class="section-label">2025년 공시 · 졸업생 ${g.graduates}명</div><h3 class="detail-title">졸업생은 어디로 진학했나요?</h3><div class="graduate-highlights"><div><small>대학교 진학</small><strong>${rate(g.university,g.graduates)}</strong><span>${g.university}명 · 전문대학 제외</span></div><div><small>대학 진학률</small><strong>${rate(g.further_total,g.graduates)}</strong><span>${g.further_total}명 · 전문대·국외 포함</span></div></div><div class="destination-list">${[['국내 대학교',g.university],['국내 전문대학',g.junior_college],['국외 진학',g.foreign_total],['취업',g.employed],['기타',g.other]].map(([label,n])=>`<div class="row"><span>${label}</span><b>${n}명</b></div>`).join('')}</div><div class="meaning">진학률은 졸업생의 선택을 보여주는 자료예요. 대학명·수시/정시·재수 인원은 이 자료에 포함되지 않습니다.</div><details class="source-details"><summary>남녀별 인원 보기</summary>${s.graduates.filter(x=>x.gender!=='합계').map(x=>`<article class="gender-graduate"><h4>${x.gender==='남'?'남학생':'여학생'} · 졸업 ${x.graduates}명</h4><p>국내 대학교 ${x.university} · 전문대 ${x.junior_college} · 국외 ${x.foreign_total} · 취업 ${x.employed} · 기타 ${x.other}명</p></article>`).join('')}</details><p class="sourcefoot">기타 인원 전체를 재수생으로 해석할 수는 없습니다. ${external(s.source,'학교알리미')}</p>`;return}originalDetail()};
const originalSidebar=sidebar;
let criteriaOpen=null;
document.addEventListener('toggle',event=>{let panel=event.target;if(panel.matches?.('.compact-sidebar > details')&&panel.isConnected){criteriaOpen=panel.open;panel.querySelector('summary > span').textContent=panel.open?'접기':'설정'}},true);
sidebar=function(){let current=document.querySelector('.compact-sidebar > details');if(current)criteriaOpen=current.open;let expanded=!matchMedia('(max-width:1199px)').matches;let shown=criteriaOpen??expanded;let html=originalSidebar();let box=document.createElement('div');box.innerHTML=html;let aside=box.querySelector('aside');return `<aside class="sidebar compact-sidebar"><details ${shown?'open':''}><summary><div><b>학교 찾기 설정</b><small>${prefs.gender==='male'?'남학생 · 20개교':'여학생 · 22개교'}${prefs.origin?' · '+esc(prefs.origin):' · 중학교 선택'}</small></div><span>${shown?'접기':'설정'}</span></summary><div class="filter-content">${aside.innerHTML.replace(/<h2>학교 찾기 설정<\/h2>/,'')}</div></details></aside>`};
const originalWishlist=wishlistView;
wishlistView=function(){let html=originalWishlist(),box=document.createElement('div');box.innerHTML=html;const csv=box.querySelector('#downloadList');csv.closest('.actions').remove();const panel=box.querySelector('#backup').closest('.panel');panel.outerHTML=`<details class="panel advanced-backup"><summary>다른 기기로 기록 옮기기</summary><p>다른 기기로 옮길 때 백업 파일을 사용하세요.</p><div class="actions"><button class="outline small" id="backup">백업 저장</button><button class="outline small" id="restore">백업 불러오기</button><button class="outline small" id="downloadList">엑셀용 CSV</button></div></details>`;let fill=box.querySelector('#fillRemaining');if(fill&&prefs.wishlist.length===(prefs.gender==='male'?20:22)){fill.nextElementSibling?.remove();fill.remove()}else if(fill){let hint=fill.nextElementSibling;let extra=document.createElement('details');extra.className='remaining-schools';fill.before(extra);extra.innerHTML='<summary>나머지 학교도 추가하기</summary>';extra.append(fill);if(hint)extra.append(hint)}let bar=document.createElement('section');bar.className='save-strip';bar.innerHTML=`<div><b>지망표 저장</b><small>${prefs.wishlist.length}개교의 순서·메모를 보기 좋게 담아요.</small></div><div class="actions"><button class="primary" id="saveJpg" ${prefs.wishlist.length?'':'disabled'}>이미지 저장</button><button class="outline" id="savePdf" ${prefs.wishlist.length?'':'disabled'}>PDF 저장</button></div>`;box.querySelector('.intro').after(bar);return box.innerHTML};
function wrapText(ctx,text,max){let paragraphs=String(text||'').replace(/\r/g,'').split('\n'),lines=[];for(let para of paragraphs){let line='';for(let ch of para){if(ctx.measureText(line+ch).width>max&&line){lines.push(line);line=''}line+=ch}lines.push(line)}return lines}
async function makeReport(){await document.fonts.ready;const W=1000,H=1414,M=70,canvases=[];let c,ctx,y,page=0;const chosen=prefs.wishlist.map(school).filter(Boolean),snapshot={gender:prefs.gender,origin:prefs.origin,notes:{...prefs.notes},times:{...prefs.times}},font=(size=21,bold=false)=>{ctx.font=`${bold?'700':'400'} ${size}px "Malgun Gothic","Apple SD Gothic Neo",sans-serif`};
function newPage(){c=document.createElement('canvas');c.width=W;c.height=H;ctx=c.getContext('2d');ctx.fillStyle='#fbfcf8';ctx.fillRect(0,0,W,H);ctx.fillStyle='#234b43';font(15,true);ctx.fillText('부천 고교 선택 나침반 · 2027',M,55);font(39,true);ctx.fillText(page?'내 지망표 · 계속':'내 지망표',M,116);font(19);ctx.fillStyle='#64766a';ctx.fillText(`${snapshot.gender==='male'?'남학생':'여학생'} · ${chosen.length}개교${snapshot.origin?' · '+snapshot.origin+' 기준':''}`,M,158);ctx.strokeStyle='#dce4d8';ctx.beginPath();ctx.moveTo(M,185);ctx.lineTo(W-M,185);ctx.stroke();ctx.fillStyle='#65756a';font(15);ctx.fillText('가족과 검토하는 참고용 지망표입니다. 공식 원서가 아닙니다.',M,H-62);ctx.fillText(`작성 ${new Date().toLocaleDateString('ko-KR')} · ${++page}`,M,H-35);canvases.push(c);y=222}
newPage();for(let [i,s] of chosen.entries()){if(y+100>H-115)newPage();ctx.fillStyle='#c16c46';font(25,true);ctx.fillText(String(i+1).padStart(2,'0'),M,y);ctx.fillStyle='#234b43';font(27,true);ctx.fillText(short(s.name),M+60,y);y+=34;font(18);ctx.fillStyle='#65756a';let distance=dist(s);let meta=[s.girls?'여학교':'남녀공학',prefs.distance&&distance!==null?`직선 ${distance.toFixed(1)}km`:'',snapshot.times[s.id]?`직접 확인한 통학 ${snapshot.times[s.id]}분`:''].filter(Boolean).join(' · ');ctx.fillText(meta,M+60,y);y+=31;let note=snapshot.notes[s.id];if(note){font(20);let lines=wrapText(ctx,note,W-2*M-60);ctx.fillStyle='#394c41';for(let line of lines){if(y+30>H-115){newPage();font(20,true);ctx.fillStyle='#234b43';ctx.fillText(`${i+1}. ${short(s.name)} · 메모 계속`,M,y);y+=35;font(20);ctx.fillStyle='#394c41'}ctx.fillText(line,M+60,y);y+=29}}y+=20;ctx.strokeStyle='#e0e6dc';ctx.beginPath();ctx.moveTo(M,y);ctx.lineTo(W-M,y);ctx.stroke();y+=42}return Promise.all(canvases.map(c=>new Promise((resolve,reject)=>c.toBlob(b=>b?resolve({canvas:c,blob:b,url:URL.createObjectURL(b)}):reject(Error('image')),'image/jpeg',.95))))}
function bytes(str){return new TextEncoder().encode(str)}
async function makePDF(pages){const chunks=[bytes('%PDF-1.4\n%Report\n')],offsets=[0];let length=chunks[0].length;const push=b=>{chunks.push(b);length+=b.length};function obj(id,head,stream){offsets[id]=length;push(bytes(id+' 0 obj\n'+head));if(stream){push(bytes('\nstream\n'));push(stream);push(bytes('\nendstream'))}push(bytes('\nendobj\n'))}obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,`<< /Type /Pages /Count ${pages.length} /Kids [${pages.map((_,i)=>`${3+i*3} 0 R`).join(' ')}] >>`);for(let [i,p] of pages.entries()){let id=3+i*3,img=new Uint8Array(await p.blob.arrayBuffer());obj(id,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /XObject << /Im0 ${id+1} 0 R >> >> /Contents ${id+2} 0 R >>`);obj(id+1,`<< /Type /XObject /Subtype /Image /Width ${p.canvas.width} /Height ${p.canvas.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${img.length} >>`,img);let cmd=bytes('q\n595.28 0 0 841.89 0 0 cm\n/Im0 Do\nQ');obj(id+2,`<< /Length ${cmd.length} >>`,cmd)}let start=length;push(bytes(`xref\n0 ${offsets.length}\n0000000000 65535 f \n`+offsets.slice(1).map(x=>String(x).padStart(10,'0')+' 00000 n \n').join('')+`trailer\n<< /Size ${offsets.length} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`));return new Blob(chunks,{type:'application/pdf'})}
function saveBlob(blob,name){let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function exportMarkup(){let p=exportPages[exportIndex];return `<div class="modalhead export-head"><div class="row"><div><h2>지망표 저장·공유</h2><p>지망 순서와 메모를 파일로 저장할 수 있어요.</p></div><button class="iconbtn" data-close aria-label="저장 창 닫기">×</button></div></div><div class="modalbody export-body"><div class="export-actions"><button class="${exportFormat==='jpg'?'primary':'outline'}" id="exportJpg">이미지 저장</button><button class="${exportFormat==='pdf'?'primary':'outline'}" id="exportPdf">PDF 저장</button>${navigator.share?'<button class="outline" id="shareReport">공유하기</button>':''}</div><p class="brief">${exportPages.length>1?`총 ${exportPages.length}페이지예요. 이미지는 페이지별로, PDF는 한 파일로 저장합니다.`:'이미지는 사진처럼, PDF는 한 문서로 저장돼요.'}</p>${exportPages.length>1?`<div class="export-pager"><button class="outline small" id="exportPrev" ${exportIndex===0?'disabled':''}>이전</button><b>${exportIndex+1} / ${exportPages.length}</b><button class="outline small" id="exportNext" ${exportIndex===exportPages.length-1?'disabled':''}>다음</button></div>`:''}<img class="report-preview" src="${p.url}" alt="저장할 지망표 ${exportIndex+1}페이지 미리보기"><p class="hint">저장한 파일은 기기의 다운로드 폴더에서 확인해 주세요.</p></div>`}
async function openExport(format){if(!prefs.wishlist.length){toast('학교를 먼저 지망표에 담아 주세요.');return}let token=++exportToken;exportFormat=format;detailSchool=null;$('#modalContent').innerHTML='<div class="modalbody"><h2>지망표를 정리하고 있어요…</h2><p>한글 메모와 순서를 담아 저장할 준비를 합니다.</p><button class="outline" data-close>닫기</button></div>';if(!$('#modal').open)$('#modal').showModal();try{let pages=await makeReport();if(token!==exportToken){pages.forEach(p=>URL.revokeObjectURL(p.url));return}exportPages.forEach(p=>URL.revokeObjectURL(p.url));exportPages=pages;exportIndex=0;$('#modalContent').innerHTML=exportMarkup()}catch{$('#modalContent').innerHTML='<div class="modalbody"><h2>이미지를 만들지 못했어요.</h2><p>메모 길이를 줄이거나 다른 브라우저에서 다시 시도해 주세요.</p><button class="outline" data-close>닫기</button></div>'}}
document.addEventListener('click',async e=>{let b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.subjectgroup){subjectGroup=b.dataset.subjectgroup;renderDocuments(school(detailSchool));return}try{switch(b.id){case 'saveJpg':await openExport('jpg');break;case 'savePdf':await openExport('pdf');break;case 'exportJpg':saveBlob(exportPages[exportIndex].blob,`2027_부천_나의지망표_${exportIndex+1}.jpg`);toast('이미지를 저장했습니다. 다운로드 폴더를 확인해 주세요.');break;case 'exportPdf':saveBlob(await makePDF(exportPages),'2027_부천_나의지망표.pdf');toast('PDF를 저장했습니다.');break;case 'exportPrev':exportIndex--;$('#modalContent').innerHTML=exportMarkup();break;case 'exportNext':exportIndex++;$('#modalContent').innerHTML=exportMarkup();break;case 'shareReport':{let jpg=exportFormat==='jpg',blob=jpg?exportPages[exportIndex].blob:await makePDF(exportPages),file=new File([blob],jpg?`나의지망표_${exportIndex+1}.jpg`:'나의지망표.pdf',{type:blob.type});if(navigator.canShare?.({files:[file]}))await navigator.share({files:[file],title:'2027 부천 내 지망표'});else{saveBlob(blob,file.name);toast('파일로 저장했습니다. 기기의 공유 기능을 이용해 주세요.')}break}}}catch(err){if(err.name!=='AbortError')toast('저장하지 못했습니다. 다시 시도해 주세요.')}});
function foldPanel(html,titles){let box=document.createElement('div');box.innerHTML=html;for(let p of [...box.querySelectorAll('.panel')]){let h=p.querySelector('h2');if(h&&titles.includes(h.textContent)){let title=h.textContent;h.remove();p.outerHTML=`<details class="panel folded-panel"><summary>${esc(title)} <span>자세히 보기 ⌄</span></summary>${p.innerHTML}</details>`}}return box.innerHTML}
const originalGuide=guideView;guideView=()=>foldPanel(originalGuide(),['지원 자격·별도 신청','공식 자료 보기','자료별 기준과 출처']);
const originalDemand=demandView;demandView=()=>{let box=document.createElement('div');box.innerHTML=foldPanel(originalDemand(),['계산에 쓰인 원자료','학교별 정원 변화']);let output=box.querySelector('#simOutput'),panel=output.closest('.panel'),h=panel.querySelector('h2'),intro=h.nextElementSibling;h.textContent='올해 입학 인원은 얼마나 될까요?';intro.textContent='지난해 입학생 비율을 올해 중3 학생 수에 적용한 예상치예요.';let advanced=document.createElement('details');advanced.className='estimate-options';advanced.innerHTML='<summary>조건을 바꿔서 계산해 보기</summary>';let male=panel.querySelector('#simMale').closest('.sliderrow'),female=panel.querySelector('#simFemale').closest('.sliderrow');advanced.append(male,female);let following=[...panel.children].filter(x=>x!==h&&x!==intro&&x!==output&&x!==advanced);for(let el of following)advanced.append(el);output.after(advanced);let numbers=box.querySelector('.page > .three');if(numbers){let reference=document.createElement('details');reference.className='panel folded-panel';reference.innerHTML='<summary>학생 수와 모집정원 보기 <span>펼치기</span></summary>';reference.append(numbers);box.querySelector('.page > .panels').after(reference)}return box.innerHTML};
const originalCompare=openCompare;
openCompare=function(){if(matchMedia('(min-width:960px) and (min-height:551px)').matches)return originalCompare();if(prefs.compare.length<2){toast('학교를 2개 이상 선택해 주세요.');return}detailSchool=null;$('#modalContent').innerHTML=`<div class="modalhead"><div class="row"><div><h2>학교 비교</h2><p>관심 학교의 정보를 비교해 보세요.</p></div><button class="iconbtn" data-close aria-label="비교 닫기">×</button></div></div><div class="modalbody compare-mobile">${prefs.compare.map(id=>{let s=school(id),g=graduate(s);return `<article class="panel"><h3>${esc(short(s.name))}</h3><p class="brief">${s.girls?'여학교':'남녀공학'} · ${esc(s.ownership)}</p><div class="destination-list"><div class="row"><span>중학교 기준</span><b>${distanceText(s)}</b></div><div class="row"><span>직접 기록한 통학시간</span><b>${prefs.times[id]?esc(prefs.times[id])+'분':'아직 입력하지 않음'}</b></div><div class="row"><span>2026 모집정원</span><b>${s.quota2026}명</b></div><div class="row"><span>2027 모집정원</span><b>${s.quota}명</b></div><div class="row"><span>모집정원 증감</span><b>${s.quota-s.quota2026>0?'+':''}${s.quota-s.quota2026}명</b></div><div class="row"><span>2025 대학교 진학률</span><b>${rate(g.university,g.graduates)}</b></div></div><p class="brief" style="margin-top:17px">1학년 국·수·영 수행평가 비율 · 2026년 2학기</p><div class="comparison-ratios">${(s.assessmentSummary||[]).map(x=>`<span>${x.subject.replace('공통','').replace('2','')} <b>${x.performance}%</b></span>`).join('')}</div><button class="outline" data-detail="${id}">학교 정보 보기</button></article>`}).join('')}<p class="meaning">정원·진학률·평가비율은 서로 다른 연도의 참고 자료입니다. 학교의 우열이나 배정 확률을 뜻하지 않습니다.</p></div>`;if(!$('#modal').open)$('#modal').showModal()};
let layoutMode=()=>matchMedia('(max-height:550px) and (max-width:1000px) and (orientation:landscape)').matches?'landscape-phone':innerWidth<600?'phone':innerWidth<960||matchMedia('(max-width:1199px) and (orientation:portrait)').matches?'tablet-portrait':innerWidth<1200?'tablet-wide':'desktop';
let previousLayout=layoutMode(),resizeTimer;
window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{let next=layoutMode();if(next!==previousLayout){previousLayout=next;if(data&&$('#modal').open&&$('#modalContent').querySelector('.comparetbl,.compare-mobile'))openCompare();}},140)});
if(data){render();renderSim()}
})();
